-- Plan 28: typed fields, tenant settings, auto-number counters, stored
-- definitions and standard Account/Contact fields. Immutable once released.
CREATE TABLE sc_catalog.settings(tenant_id text PRIMARY KEY REFERENCES public.tenants(id) ON DELETE CASCADE,currency_iso_code char(3) NOT NULL DEFAULT 'USD' CHECK(currency_iso_code ~ '^[A-Z]{3}$'));
CREATE TABLE sc_catalog.auto_numbers(tenant_id text NOT NULL,field_id text NOT NULL REFERENCES sc_catalog.fields(id) ON DELETE CASCADE,next_value bigint NOT NULL CHECK(next_value>=0),PRIMARY KEY(tenant_id,field_id));
ALTER TABLE sc_catalog.artifacts ADD COLUMN object_id text,ADD COLUMN api_name text,ADD COLUMN kind text,ADD FOREIGN KEY(tenant_id,object_id) REFERENCES sc_catalog.objects(tenant_id,id) ON DELETE CASCADE;
CREATE UNIQUE INDEX artifact_names ON sc_catalog.artifacts(tenant_id,object_id,lower(api_name)) WHERE api_name IS NOT NULL;
DO $$
DECLARE r text;
BEGIN
 FOREACH r IN ARRAY ARRAY['settings','auto_numbers'] LOOP
  EXECUTE format('ALTER TABLE sc_catalog.%I OWNER TO salescompel_owner',r);
  EXECUTE format('ALTER TABLE sc_catalog.%I ENABLE ROW LEVEL SECURITY',r);
  EXECUTE format('ALTER TABLE sc_catalog.%I FORCE ROW LEVEL SECURITY',r);
  EXECUTE format('CREATE POLICY tenant_isolation ON sc_catalog.%I USING(tenant_id=nullif(current_setting(''salescompel.tenant_id'',true),'''')) WITH CHECK(tenant_id=nullif(current_setting(''salescompel.tenant_id'',true),''''))',r);
 END LOOP;
END $$;
GRANT SELECT ON sc_catalog.settings TO salescompel_records;
GRANT SELECT,UPDATE ON sc_catalog.auto_numbers TO salescompel_records;

ALTER TABLE public.accounts
 ADD COLUMN phone varchar(40),
 ADD COLUMN fax varchar(40),
 ADD COLUMN website varchar(255),
 ADD COLUMN type varchar(255),
 ADD COLUMN industry varchar(255),
 ADD COLUMN annual_revenue numeric(18,0),
 ADD COLUMN number_of_employees numeric(8,0),
 ADD COLUMN description text CHECK(char_length(description)<=32000),
 ADD COLUMN billing_street varchar(255),
 ADD COLUMN billing_city varchar(40),
 ADD COLUMN billing_state varchar(80),
 ADD COLUMN billing_postal_code varchar(20),
 ADD COLUMN billing_country varchar(80),
 ADD COLUMN shipping_street varchar(255),
 ADD COLUMN shipping_city varchar(40),
 ADD COLUMN shipping_state varchar(80),
 ADD COLUMN shipping_postal_code varchar(20),
 ADD COLUMN shipping_country varchar(80);
ALTER TABLE public.contacts
 ADD COLUMN salutation varchar(255),
 ADD COLUMN name text GENERATED ALWAYS AS (nullif(btrim(coalesce(first_name,'')||' '||last_name),'')) STORED,
 ADD COLUMN title varchar(128),
 ADD COLUMN department varchar(80),
 ADD COLUMN email varchar(80),
 ADD COLUMN phone varchar(40),
 ADD COLUMN mobile_phone varchar(40),
 ADD COLUMN birthdate date,
 ADD COLUMN description text CHECK(char_length(description)<=32000),
 ADD COLUMN mailing_street varchar(255),
 ADD COLUMN mailing_city varchar(40),
 ADD COLUMN mailing_state varchar(80),
 ADD COLUMN mailing_postal_code varchar(20),
 ADD COLUMN mailing_country varchar(80);

-- Catalog rows are written per tenant with that tenant's context, so forced
-- row security holds even when the operator is not a superuser.
DO $$
DECLARE tid text;
BEGIN
 FOR tid IN SELECT id FROM public.tenants ORDER BY id LOOP
  PERFORM set_config('salescompel.tenant_id',tid,true);
  CONTINUE WHEN NOT EXISTS(SELECT FROM sc_catalog.revisions WHERE tenant_id=tid);
  INSERT INTO sc_catalog.settings(tenant_id) VALUES(tid);
  UPDATE sc_catalog.fields f SET definition=jsonb_build_object('v',2,
   'field','{"soapType":"xsd:string","precision":0,"scale":0,"digits":0,"relationshipName":null,"relationshipOrder":null,"cascadeDelete":false,"restrictedDelete":false,"picklistValues":[],"restrictedPicklist":false,"dependentPicklist":false,"autoNumber":false,"calculated":false,"defaultValue":null,"defaultedOnCreate":false,"nameField":false,"compoundFieldName":null,"htmlFormatted":false,"filterable":true,"sortable":true,"groupable":true,"unique":false}'::jsonb||f.definition
    ||jsonb_build_object('soapType',CASE f.definition->>'type' WHEN 'string' THEN 'xsd:string' ELSE 'tns:ID' END)
    ||CASE WHEN f.api_name='Name' THEN '{"nameField":true}'::jsonb ELSE '{}'::jsonb END
    ||CASE WHEN o.standard AND o.api_name='Contact' AND f.api_name IN ('FirstName','LastName') THEN '{"compoundFieldName":"Name"}'::jsonb ELSE '{}'::jsonb END
    ||CASE WHEN o.standard AND o.api_name='Contact' AND f.api_name='AccountId' THEN '{"relationshipName":"Account","restrictedDelete":true}'::jsonb ELSE '{}'::jsonb END,
   'options',jsonb_build_object('kind',CASE f.definition->>'type' WHEN 'id' THEN 'Id' WHEN 'string' THEN 'Text' WHEN 'reference' THEN 'Lookup' END)
    ||CASE WHEN f.definition->>'type'='reference' THEN '{"deleteBehavior":"Restrict"}'::jsonb ELSE '{}'::jsonb END)
  FROM sc_catalog.objects o WHERE o.tenant_id=f.tenant_id AND o.id=f.object_id AND f.tenant_id=tid AND NOT f.definition ? 'v';
  INSERT INTO sc_catalog.fields SELECT md5('field:'||tid||':Account:Phone'),tid,o.id,'Phone','phone','{"v":2,"field":{"name":"Phone","label":"Account Phone","type":"phone","soapType":"xsd:string","nillable":true,"createable":true,"updateable":true,"externalId":false,"length":40,"precision":0,"scale":0,"digits":0,"referenceTo":[],"relationshipName":null,"relationshipOrder":null,"cascadeDelete":false,"restrictedDelete":false,"picklistValues":[],"restrictedPicklist":false,"dependentPicklist":false,"autoNumber":false,"calculated":false,"defaultValue":null,"defaultedOnCreate":false,"nameField":false,"compoundFieldName":null,"htmlFormatted":false,"filterable":true,"sortable":true,"groupable":true,"unique":false},"options":{"kind":"Phone"}}'::jsonb,4 FROM sc_catalog.objects o WHERE o.tenant_id=tid AND o.api_name='Account' AND o.standard;
  INSERT INTO sc_catalog.fields SELECT md5('field:'||tid||':Account:Fax'),tid,o.id,'Fax','fax','{"v":2,"field":{"name":"Fax","label":"Account Fax","type":"phone","soapType":"xsd:string","nillable":true,"createable":true,"updateable":true,"externalId":false,"length":40,"precision":0,"scale":0,"digits":0,"referenceTo":[],"relationshipName":null,"relationshipOrder":null,"cascadeDelete":false,"restrictedDelete":false,"picklistValues":[],"restrictedPicklist":false,"dependentPicklist":false,"autoNumber":false,"calculated":false,"defaultValue":null,"defaultedOnCreate":false,"nameField":false,"compoundFieldName":null,"htmlFormatted":false,"filterable":true,"sortable":true,"groupable":true,"unique":false},"options":{"kind":"Phone"}}'::jsonb,5 FROM sc_catalog.objects o WHERE o.tenant_id=tid AND o.api_name='Account' AND o.standard;
  INSERT INTO sc_catalog.fields SELECT md5('field:'||tid||':Account:Website'),tid,o.id,'Website','website','{"v":2,"field":{"name":"Website","label":"Website","type":"url","soapType":"xsd:string","nillable":true,"createable":true,"updateable":true,"externalId":false,"length":255,"precision":0,"scale":0,"digits":0,"referenceTo":[],"relationshipName":null,"relationshipOrder":null,"cascadeDelete":false,"restrictedDelete":false,"picklistValues":[],"restrictedPicklist":false,"dependentPicklist":false,"autoNumber":false,"calculated":false,"defaultValue":null,"defaultedOnCreate":false,"nameField":false,"compoundFieldName":null,"htmlFormatted":false,"filterable":true,"sortable":true,"groupable":true,"unique":false},"options":{"kind":"Url"}}'::jsonb,6 FROM sc_catalog.objects o WHERE o.tenant_id=tid AND o.api_name='Account' AND o.standard;
  INSERT INTO sc_catalog.fields SELECT md5('field:'||tid||':Account:Type'),tid,o.id,'Type','type','{"v":2,"field":{"name":"Type","label":"Account Type","type":"picklist","soapType":"xsd:string","nillable":true,"createable":true,"updateable":true,"externalId":false,"length":255,"precision":0,"scale":0,"digits":0,"referenceTo":[],"relationshipName":null,"relationshipOrder":null,"cascadeDelete":false,"restrictedDelete":false,"picklistValues":[{"active":true,"defaultValue":false,"label":"Prospect","value":"Prospect","validFor":null},{"active":true,"defaultValue":false,"label":"Customer - Direct","value":"Customer - Direct","validFor":null},{"active":true,"defaultValue":false,"label":"Customer - Channel","value":"Customer - Channel","validFor":null},{"active":true,"defaultValue":false,"label":"Channel Partner / Reseller","value":"Channel Partner / Reseller","validFor":null},{"active":true,"defaultValue":false,"label":"Installation Partner","value":"Installation Partner","validFor":null},{"active":true,"defaultValue":false,"label":"Technology Partner","value":"Technology Partner","validFor":null},{"active":true,"defaultValue":false,"label":"Other","value":"Other","validFor":null}],"restrictedPicklist":false,"dependentPicklist":false,"autoNumber":false,"calculated":false,"defaultValue":null,"defaultedOnCreate":false,"nameField":false,"compoundFieldName":null,"htmlFormatted":false,"filterable":true,"sortable":true,"groupable":true,"unique":false},"options":{"kind":"Picklist"}}'::jsonb,7 FROM sc_catalog.objects o WHERE o.tenant_id=tid AND o.api_name='Account' AND o.standard;
